#!/usr/bin/python3
"""Tests for honey-initd-lint (generated by agents-bots-honey.org). Pure Python: no root, no OpenRC, no network, reads only its own fixtures.
HONEY_INITD_LINT=/path overrides the lint under test (the mutation proof uses it)."""
import importlib.machinery, importlib.util, json, os, subprocess, sys, tempfile, unittest

HERE = os.path.dirname(os.path.abspath(__file__))
CANDIDATES = [os.environ.get('HONEY_INITD_LINT', ''), os.path.join(HERE, '..', '..', '..', 'bin', 'honey-initd-lint'), os.path.join(HERE, 'honey-initd-lint')]
LINT = next(os.path.abspath(c) for c in CANDIDATES if c and os.path.isfile(c))
WATCH = next((c for c in (os.environ.get('HONEY_INITD_LINT_WATCH', ''), os.path.join(HERE, '..', '..', '..', 'bin', 'honey-initd-lint-watch'), os.path.join(HERE, 'honey-initd-lint-watch')) if c and os.path.isfile(c)), None)
PROOF = next((os.path.join(HERE, n) for n in ('initd-stop-proof',) if os.path.isfile(os.path.join(HERE, n))), None)
_spec = importlib.util.spec_from_loader('initd_lint', importlib.machinery.SourceFileLoader('initd_lint', LINT))
lint = importlib.util.module_from_spec(_spec); _spec.loader.exec_module(lint)

OPENRC = '#!/sbin/openrc-run\n'
SAFE_STOP = '''
stop() {
    local pid
    pid="$(cat "${pidfile}" 2>/dev/null)"
    [ -n "${pid}" ] || return 0
    ebegin "Stopping ${RC_SVCNAME}"
    start-stop-daemon --stop --quiet --retry TERM/5/KILL/3 --pidfile "${pidfile}"
    eend $?
}
'''
PY = OPENRC + 'command="/usr/bin/python3"\ncommand_args="-I /opt/x/relay.py"\ncommand_background=true\npidfile="/run/${RC_SVCNAME}.pid"\n'


def wr(path, text):
    with open(path, 'w') as fh:
        fh.write(text)


def rd(path):
    with open(path) as fh:
        return fh.read()


def run(text, name='svc', confd=None):
    return lint.analyse_text(name, text, confd)


def rules(res):
    return sorted(r for _, r, _ in res['faults'])


class Rule1NoOwnStop(unittest.TestCase):
    def test_python3_without_stop_is_the_fault_that_killed_seven_services(self):
        r = run(PY)
        self.assertEqual(r['status'], 'FAULT'); self.assertEqual(rules(r), ['no-own-stop'])

    def test_the_fault_names_the_line_of_command(self):
        r = run(PY)
        self.assertEqual(r['faults'][0][0], 2)

    def test_every_shared_interpreter_name_is_caught(self):
        for exe in ('/usr/bin/python3', '/usr/bin/python', '/usr/bin/python3.13', '/usr/bin/perl', '/bin/bash', '/bin/sh', '/usr/bin/node', '/usr/bin/ruby', '/venv/bin/python3'):
            with self.subTest(exe=exe):
                self.assertEqual(run(OPENRC + 'command="%s"\npidfile=/run/x.pid\n' % exe)['status'], 'FAULT')

    def test_a_specific_daemon_is_not_applicable(self):
        r = run(OPENRC + 'command="/usr/bin/syncthing"\npidfile=/run/x.pid\n')
        self.assertEqual(r['status'], 'NA'); self.assertEqual(r['faults'], [])

    def test_a_script_that_merely_runs_under_python_is_not_shared(self):
        self.assertEqual(run(OPENRC + 'command="/home/u/bin/llama-swap-bridge-relay.py"\n')['status'], 'NA')

    def test_default_expansion_resolves_to_the_interpreter(self):
        r = run(OPENRC + 'command="${py:-/usr/bin/python3}"\n')
        self.assertEqual(r['status'], 'FAULT')

    def test_conf_d_is_sourced_first_so_it_feeds_defaults_but_a_plain_assignment_in_the_script_wins(self):
        with tempfile.TemporaryDirectory() as d:
            wr(os.path.join(d, 'svc'), 'py=/opt/app/bin/app-server\n')
            self.assertEqual(run(OPENRC + 'command="${py:-/usr/bin/python3}"\n', confd=d)['status'], 'NA')
            wr(os.path.join(d, 'svc'), 'py=/usr/bin/python3\n')
            self.assertEqual(run(OPENRC + 'command="${py:-/opt/app/bin/app-server}"\n', confd=d)['status'], 'FAULT')
            wr(os.path.join(d, 'svc'), 'command=/usr/bin/python3\n')  # a plain assignment in the script is sourced later and wins
            self.assertEqual(run(OPENRC + 'command=/opt/app/bin/app-server\n', confd=d)['status'], 'NA')

    def test_a_variable_set_earlier_in_the_script_is_followed(self):
        self.assertEqual(run(OPENRC + 'interp=/usr/bin/python3\ncommand="${interp}"\n')['status'], 'FAULT')

    def test_procname_naming_an_interpreter_is_shared(self):
        self.assertEqual(run(OPENRC + 'command="/opt/x/server"\nprocname=python3\n')['status'], 'FAULT')

    def test_an_own_stop_clears_it(self):
        r = run(PY + SAFE_STOP)
        self.assertEqual((r['status'], r['faults']), ('OK', []))

    def test_conf_d_default_assignment_form_is_followed(self):
        self.assertEqual(run(OPENRC + ': "${command:=/usr/bin/python3}"\n')['status'], 'FAULT')


class Rule2StopPassesExec(unittest.TestCase):
    def stop_with(self, line):
        return run(PY + 'stop() {\n    %s\n}\n' % line)

    def test_exec_python3_in_stop_is_a_fault_that_looks_like_a_fix(self):
        r = self.stop_with('start-stop-daemon --stop --exec /usr/bin/python3 --pidfile "${pidfile}"')
        self.assertEqual(rules(r), ['stop-exec'])

    def test_exec_through_the_command_variable_is_a_fault(self):
        self.assertEqual(rules(self.stop_with('start-stop-daemon --stop --exec "${command}" --pidfile "${pidfile}"')), ['stop-exec'])

    def test_short_and_equals_forms_are_caught(self):
        for form in ('-x /usr/bin/python3', '--exec=/usr/bin/python3', '-x/usr/bin/python3'):
            with self.subTest(form=form):
                self.assertEqual(rules(self.stop_with('start-stop-daemon -K %s -p "${pidfile}"' % form)), ['stop-exec'])

    def test_exec_of_a_specific_binary_is_not_a_fault(self):
        r = run(OPENRC + 'command="/opt/x/relay-server"\n' + 'stop() {\n    start-stop-daemon --stop --exec /opt/x/relay-server --pidfile "${pidfile}"\n}\n')
        self.assertEqual(r['status'], 'OK')

    def test_unresolvable_exec_on_a_shared_daemon_is_a_fault_but_on_others_unparsed(self):
        self.assertEqual(rules(self.stop_with('start-stop-daemon --stop --exec "${mystery}" --pidfile "${pidfile}"')), ['stop-exec'])
        r = run(OPENRC + 'command="/opt/x/server"\nstop() {\n    start-stop-daemon --stop --exec "${mystery}" --pidfile "${pidfile}"\n}\n')
        self.assertEqual(r['status'], 'UNPARSED'); self.assertEqual(r['line'], 4)

    def test_exec_in_stop_pre_and_stop_post_counts(self):
        for fn in ('stop_pre', 'stop_post'):
            with self.subTest(fn=fn):
                r = run(PY + SAFE_STOP + '%s() {\n    start-stop-daemon --stop --exec /usr/bin/python3\n}\n' % fn)
                self.assertEqual(rules(r), ['stop-exec'])

    def test_exec_in_a_comment_or_a_string_is_not_a_call(self):
        r = run(PY + 'stop() {\n    # never pass --exec /usr/bin/python3 here\n    einfo "no --exec /usr/bin/python3 --stop"\n    start-stop-daemon --stop --pidfile "${pidfile}"\n}\n')
        self.assertEqual(r['status'], 'OK')

    def test_the_landed_egress_unit_passes(self):
        unit = os.path.join(HERE, '..', 'honey-fca-dsh', 'openrc', 'honey-fca-egress')
        if not os.path.isfile(unit):
            self.skipTest('SKIPPED: the relay unit is not beside this lane')
        r = lint.analyse_file(unit, None)
        self.assertEqual((r['status'], r['faults']), ('OK', []))


class Rule3SignalsByNameOrPattern(unittest.TestCase):
    def stop_with(self, body, head=PY):
        return run(head + 'stop() {\n%s\n}\n' % body)

    def test_pkill_python3_is_a_fault(self):
        self.assertEqual(rules(self.stop_with('    pkill python3')), ['stop-by-name'])

    def test_pkill_pattern_on_a_shared_daemon_is_a_fault_even_with_a_uid(self):
        self.assertEqual(rules(self.stop_with('    pkill -u svc -f relay.py')), ['stop-by-name'])

    def test_unscoped_pattern_signal_is_a_fault_even_on_a_specific_daemon(self):
        r = self.stop_with('    pkill -f my-daemon', head=OPENRC + 'command="/opt/x/my-daemon"\n')
        self.assertEqual(rules(r), ['stop-by-name'])

    def test_uid_scoped_specific_pattern_on_a_specific_daemon_is_only_a_note(self):
        r = self.stop_with('    pkill -TERM -u "${warm_user}" -f "/home/u/.local/bin/warm" 2>/dev/null', head=OPENRC + 'command="/opt/x/my-daemon"\nwarm_user=svc\n')
        self.assertEqual((r['status'], r['faults']), ('OK', [])); self.assertEqual(len(r['notes']), 1)

    def test_bare_interpreter_pattern_is_a_fault_even_when_uid_scoped(self):
        r = self.stop_with('    pkill -u svc -f python3', head=OPENRC + 'command="/opt/x/my-daemon"\n')
        self.assertEqual(rules(r), ['stop-by-name'])

    def test_killall_is_caught(self):
        self.assertEqual(rules(self.stop_with('    killall -TERM relay', head=OPENRC + 'command="/opt/x/relay"\n')), ['stop-by-name'])

    def test_kill_of_a_pgrep_substitution_is_caught(self):
        self.assertEqual(rules(self.stop_with('    kill -TERM $(pgrep -f relay.py)', head=OPENRC + 'command="/opt/x/relay"\n')), ['stop-by-name'])

    def test_pgrep_piped_to_xargs_kill_is_caught(self):
        self.assertEqual(rules(self.stop_with('    pgrep -f relay.py | xargs kill', head=OPENRC + 'command="/opt/x/relay"\n')), ['stop-by-name'])

    def test_pgrep_alone_is_not_a_signal(self):
        r = self.stop_with('    while pgrep -f relay.py >/dev/null 2>&1; do sleep 1; done', head=OPENRC + 'command="/opt/x/relay"\n')
        self.assertEqual((r['status'], r['faults'], r['notes']), ('OK', [], []))

    def test_start_stop_daemon_name_python3_is_a_fault(self):
        self.assertEqual(rules(self.stop_with('    start-stop-daemon --stop --name python3 --pidfile "${pidfile}"')), ['stop-by-name'])

    def test_a_specific_ssd_name_is_a_note(self):
        r = self.stop_with('    start-stop-daemon --stop --name udevd', head=OPENRC + 'command="/opt/x/relay"\n')
        self.assertEqual(r['faults'], []); self.assertEqual(len(r['notes']), 1)

    def test_signal_by_pidfile_or_by_pid_is_fine(self):
        r = self.stop_with('    local pid; pid="$(cat "${pidfile}")"\n    kill -TERM "${pid}"\n    kill -0 "${pid}" && kill -KILL "${pid}"')
        self.assertEqual((r['status'], r['faults']), ('OK', []))

    def test_signal_by_ssd_uid_and_pidfile_is_fine(self):
        r = self.stop_with('    start-stop-daemon --stop --user svc --pidfile "${pidfile}"')
        self.assertEqual((r['status'], r['faults']), ('OK', []))

    def test_pkill_inside_sh_c_and_su_c_is_still_seen(self):
        for wrap in ('su -l svc -c "pkill python3"', "sh -c 'pkill python3'"):
            with self.subTest(wrap=wrap):
                self.assertEqual(rules(self.stop_with('    ' + wrap)), ['stop-by-name'])

    def test_a_function_that_is_not_stop_family_is_not_examined(self):
        r = run(PY + SAFE_STOP + 'start_pre() {\n    pkill -f stale-thing\n}\n')
        self.assertEqual(r['status'], 'OK')

    def test_a_comment_with_an_apostrophe_or_a_brace_does_not_break_parsing(self):
        r = run(PY + "stop() {\n    # it's a { odd comment\n    start-stop-daemon --stop --pidfile \"${pidfile}\"  # not --exec\n}\n")
        self.assertEqual((r['status'], r['faults']), ('OK', []))

    def test_pkill_in_a_comment_or_heredoc_is_not_a_call(self):
        r = run(PY + SAFE_STOP + "stop_post() {\n    # pkill python3\n    cat <<'EOF'\npkill python3\nstop() {\nEOF\n    rm -f /run/x.sock\n}\n")
        self.assertEqual(r['status'], 'OK')


class UnparsedIsNeverAVerdict(unittest.TestCase):
    def test_unterminated_quote_reports_the_line(self):
        r = run(OPENRC + 'command="/usr/bin/python3"\necho "oops\n')
        self.assertEqual(r['status'], 'UNPARSED'); self.assertEqual(r['line'], 3); self.assertIn('quote', r['why'])

    def test_unbalanced_function_reports_the_line_where_it_opened(self):
        r = run(OPENRC + 'command="/opt/x/y"\nstop() {\n    echo hi\n')
        self.assertEqual((r['status'], r['line']), ('UNPARSED', 3))

    def test_computed_command_without_a_stop_is_unparsed_with_its_line(self):
        r = run(OPENRC + 'user_home="$(getent passwd u | cut -d: -f6)"\ncommand="${user_home}"\n')
        self.assertEqual((r['status'], r['line']), ('UNPARSED', 3))

    def test_computed_prefix_with_a_literal_specific_tail_is_decidable(self):
        r = run(OPENRC + 'user_home="$(getent passwd u | cut -d: -f6)"\ncommand="${user_home}/.local/bin/ductor"\n')
        self.assertEqual(r['status'], 'NA')

    def test_computed_prefix_with_a_literal_interpreter_tail_is_a_fault(self):
        r = run(OPENRC + 'user_home="$(getent passwd u | cut -d: -f6)"\ncommand="${user_home}/venv/bin/python3"\n')
        self.assertEqual(r['status'], 'FAULT')

    def test_no_shebang_is_unparsed(self):
        r = run('some text\n')
        self.assertEqual((r['status'], r['line']), ('UNPARSED', 1))

    def test_supervise_daemon_on_a_shared_interpreter_is_unparsed_not_a_fault(self):
        self.assertEqual(run(PY + 'supervisor=supervise-daemon\n')['status'], 'UNPARSED')

    def test_supervise_daemon_on_a_specific_daemon_is_not_applicable(self):
        self.assertEqual(run(OPENRC + 'supervisor=supervise-daemon\ncommand=/sbin/agetty\n')['status'], 'NA')

    def test_a_subshell_function_body_is_unparsed(self):
        self.assertEqual(run(PY + 'stop() ( pkill python3 )\n')['status'], 'UNPARSED')

    def test_exit_status_ignores_unparsed(self):
        with tempfile.TemporaryDirectory() as d:
            wr(os.path.join(d, 'a'), 'no shebang\n')
            wr(os.path.join(d, 'b'), OPENRC + 'command="/opt/x/y"\necho "oops\n')
            p = subprocess.run([sys.executable, '-I', LINT, '--dir', d, '--confd', d + '/none'], capture_output=True, text=True)
            self.assertEqual(p.returncode, 0, p.stdout)
            self.assertIn('unparsed=2', p.stdout); self.assertIn('UNPARSED %s/b:3' % d, p.stdout)

    def test_a_bug_in_the_lint_is_unparsed_for_that_file_never_a_pass_or_a_fault(self):
        saved = lint.analyse_text
        try:
            lint.analyse_text = lambda *a, **k: 1 / 0
            with tempfile.TemporaryDirectory() as d:
                p = os.path.join(d, 'x'); wr(p, OPENRC)
                r = lint.analyse_file(p, None)
                self.assertEqual(r['status'], 'UNPARSED'); self.assertIn('ZeroDivisionError', r['why'])
        finally:
            lint.analyse_text = saved


class SysvScripts(unittest.TestCase):
    HEAD = '#!/bin/sh\nDAEMON=/usr/bin/python3\nPIDFILE=/var/run/x.pid\ncase "$1" in\n  start) start-stop-daemon --start --pidfile $PIDFILE --exec $DAEMON -- /opt/x.py ;;\n'

    def test_stop_by_pidfile_only_is_fine(self):
        r = run(self.HEAD + '  stop) start-stop-daemon --stop --pidfile $PIDFILE ;;\nesac\n')
        self.assertEqual((r['status'], r['faults']), ('NA', []))

    def test_stop_by_exec_alone_on_an_interpreter_is_a_fault(self):
        r = run(self.HEAD + '  stop) start-stop-daemon --stop --exec $DAEMON ;;\nesac\n')
        self.assertEqual(rules(r), ['stop-exec'])

    def test_exec_next_to_a_pidfile_narrows_the_match_and_is_accepted(self):
        r = run(self.HEAD + '  stop) start-stop-daemon --stop --exec $DAEMON --pidfile $PIDFILE ;;\nesac\n')
        self.assertEqual(r['faults'], [])

    def test_pkill_python3_in_a_sysv_script_is_a_fault(self):
        r = run(self.HEAD + '  stop) pkill python3 ;;\nesac\n')
        self.assertEqual(rules(r), ['stop-by-name'])

    def test_continuation_lines_are_joined(self):
        r = run(self.HEAD + '  stop) start-stop-daemon --stop \\\n      --exec /usr/bin/python3 ;;\nesac\n')
        self.assertEqual(rules(r), ['stop-exec'])


class DirectoryRun(unittest.TestCase):
    def tree(self, files):
        d = tempfile.mkdtemp(); self.addCleanup(lambda: __import__('shutil').rmtree(d, ignore_errors=True))
        for n, t in files.items():
            os.makedirs(os.path.dirname(os.path.join(d, n)), exist_ok=True)
            if t is None: os.mkdir(os.path.join(d, n))
            else: wr(os.path.join(d, n), t)
        return d

    def cli(self, d, *extra):
        return subprocess.run([sys.executable, '-I', LINT, '--dir', d, '--confd', d + '/none', *extra], capture_output=True, text=True)

    def test_exit_1_on_a_proven_fault_and_the_summary_counts_add_up(self):
        d = self.tree({'bad': PY, 'good': PY + SAFE_STOP, 'other': OPENRC + 'command=/usr/bin/syncthing\n', 'junk': 'x\n'})
        p = self.cli(d)
        self.assertEqual(p.returncode, 1, p.stdout)
        self.assertIn('scanned=4 active=4 ok=1 not_applicable=1 fault=1 unparsed=1', p.stdout)
        self.assertIn('RESULT FAIL', p.stdout)

    def test_exit_0_and_a_pass_line_when_no_active_script_is_faulty(self):
        p = self.cli(self.tree({'good': PY + SAFE_STOP}))
        self.assertEqual(p.returncode, 0); self.assertIn('RESULT PASS', p.stdout)

    def test_backup_copies_are_reported_but_never_change_the_exit(self):
        d = self.tree({'svc': PY + SAFE_STOP, 'svc.bak-2026-10-01': PY, 'svc.orig': PY, 'old.disabled': PY, 'hermes.retired-handrolled': PY, 'svc~': PY})
        p = self.cli(d)
        self.assertEqual(p.returncode, 0, p.stdout)
        self.assertIn('scanned=6 active=1', p.stdout); self.assertIn('inactive_copies=5 inactive_copies_with_fault=5', p.stdout)
        self.assertIn('FAULT (inactive copy)', p.stdout)

    def test_dotfiles_and_directories_are_not_scripts(self):
        d = self.tree({'.depend.boot': 'TARGETS = x\n', 'sub': None, 'svc': PY + SAFE_STOP})
        p = self.cli(d, '--json'); j = json.loads(p.stdout)
        self.assertEqual(j['summary']['scanned'], 1); self.assertEqual(j['directories_skipped'], 2)

    def test_json_carries_the_summary_the_exit_and_each_finding(self):
        d = self.tree({'bad': PY})
        j = json.loads(self.cli(d, '--json').stdout)
        self.assertEqual((j['exit'], j['summary']['fault']), (1, 1))
        self.assertEqual(j['results'][0]['faults'][0][1], 'no-own-stop')

    def test_an_unreadable_directory_is_exit_2(self):
        p = subprocess.run([sys.executable, '-I', LINT, '--dir', '/nonexistent-init-d'], capture_output=True, text=True)
        self.assertEqual(p.returncode, 2)

    def test_unknown_option_is_exit_2(self):
        self.assertEqual(subprocess.run([sys.executable, '-I', LINT, '--bogus'], capture_output=True, text=True).returncode, 2)

    def test_the_lint_reads_and_never_runs_a_script(self):
        marker = os.path.join(tempfile.gettempdir(), 'initd-lint-ran-%d' % os.getpid())
        d = self.tree({'trap': OPENRC + 'touch %s\ncommand=/opt/x/y\nstop() {\n  touch %s\n}\n' % (marker, marker)})
        self.cli(d)
        self.assertFalse(os.path.exists(marker))

    def test_explicit_file_arguments_are_linted(self):
        d = self.tree({'bad': PY})
        p = subprocess.run([sys.executable, '-I', LINT, os.path.join(d, 'bad')], capture_output=True, text=True)
        self.assertEqual(p.returncode, 1)


class ParserDetails(unittest.TestCase):
    def test_brace_on_the_next_line_and_one_line_functions(self):
        for body in ('stop()\n{\n    start-stop-daemon --stop --pidfile "${pidfile}"\n}\n', 'stop() { start-stop-daemon --stop --pidfile "${pidfile}"; }\n',
                     'function stop {\n}\n' if False else 'stop() {\n    local x="${y:-{}}"\n    start-stop-daemon --stop --pidfile "${pidfile}"\n}\n'):
            with self.subTest(body=body):
                self.assertEqual(run(PY + body)['status'], 'OK')

    def test_continuation_lines_join_in_openrc_stop(self):
        r = run(PY + 'stop() {\n    start-stop-daemon --stop \\\n        --exec /usr/bin/python3 \\\n        --pidfile "${pidfile}"\n}\n')
        self.assertEqual(rules(r), ['stop-exec'])

    def test_a_quoted_semicolon_does_not_split_a_command(self):
        r = run(PY + SAFE_STOP + 'stop_post() {\n    einfo "pkill python3; really"\n}\n')
        self.assertEqual(r['status'], 'OK')

    def test_redirections_are_not_taken_for_patterns(self):
        r = run(OPENRC + 'command=/opt/x/relay\nstop() {\n    pkill -u svc -f /opt/x/relay 2>/dev/null >/dev/null\n}\n')
        self.assertEqual(r['faults'], []); self.assertIn('/opt/x/relay', r['notes'][0][1])

    def test_dollar_paren_command_values_are_not_resolved(self):
        self.assertIsNone(lint.expand('$(getent passwd x)', {}))
        self.assertIsNone(lint.expand('${undefined}/x', {}))
        self.assertEqual(lint.expand('${a:-b}/c', {}), 'b/c')
        self.assertEqual(lint.expand('${a:-b}/c', {'a': 'z'}), 'z/c')

    def test_default_that_contains_a_path_is_not_an_unsupported_operator(self):
        self.assertEqual(lint.expand('${honey_voice_python:-/usr/bin/python3}', {}), '/usr/bin/python3')


@unittest.skipUnless(WATCH and all(subprocess.run(['sh', '-c', 'command -v ' + c], capture_output=True).returncode == 0 for c in ('flock', 'sha256sum', 'xargs')),
                     'SKIPPED: honey-initd-lint-watch or flock/sha256sum/xargs is not available')
class Watcher(unittest.TestCase):
    def setUp(self):
        self.d = tempfile.mkdtemp(); self.addCleanup(lambda: __import__('shutil').rmtree(self.d, ignore_errors=True))
        for sub in ('init.d', 'conf.d', 'state'):
            os.mkdir(os.path.join(self.d, sub))
        wr(os.path.join(self.d, 'init.d', 'good'), PY + SAFE_STOP)
        self.alert = os.path.join(self.d, 'alert.sh'); wr(self.alert, '#!/bin/sh\necho "$1" >> %s/alerts\n' % self.d); os.chmod(self.alert, 0o755)

    def watch(self, *a, alert=True):
        env = dict(os.environ, HONEY_INITD_LINT=LINT, HONEY_INITD_DIR=self.d + '/init.d', HONEY_INITD_CONFD=self.d + '/conf.d', HONEY_INITD_LINT_STATE=self.d + '/state')
        env.pop('HONEY_INITD_LINT_ALERT', None)
        if alert: env['HONEY_INITD_LINT_ALERT'] = self.alert
        return subprocess.run(['bash', WATCH, *a], capture_output=True, text=True, env=env, timeout=60)

    def history(self):
        p = os.path.join(self.d, 'state', 'history.log')
        return rd(p).splitlines() if os.path.exists(p) else []

    def alerts(self):
        p = os.path.join(self.d, 'alerts')
        return rd(p).splitlines() if os.path.exists(p) else []

    def test_first_run_records_a_status_line_and_exits_clean(self):
        self.assertEqual(self.watch().returncode, 0)
        self.assertRegex(rd(os.path.join(self.d, 'state', 'status')), r' rc=0 fault=0 unparsed=0 scanned=1 faulting=none')

    def test_an_unchanged_tree_is_not_linted_again(self):
        self.watch(); self.watch(); self.watch()
        self.assertEqual(len(self.history()), 1)

    def test_a_changed_init_script_triggers_a_run_and_a_new_fault_exits_1(self):
        self.watch()
        wr(os.path.join(self.d, 'init.d', 'newsvc'), PY)
        p = self.watch()
        self.assertEqual(p.returncode, 1); self.assertEqual(len(self.history()), 2)
        self.assertIn('faulting=newsvc', self.history()[-1])

    def test_a_changed_conf_d_triggers_a_run(self):
        self.watch(); wr(os.path.join(self.d, 'conf.d', 'good'), 'x=1\n'); self.watch()
        self.assertEqual(len(self.history()), 2)

    def test_an_edit_that_keeps_the_size_and_mtime_is_still_seen(self):
        p = os.path.join(self.d, 'init.d', 'a'); wr(p, OPENRC + 'command=/opt/x/aaa\n'); self.watch()
        st = os.stat(p); wr(p, OPENRC + 'command=/opt/x/bbb\n'); os.utime(p, (st.st_atime, st.st_mtime)); self.watch()
        self.assertEqual(len(self.history()), 2)

    def test_a_stale_status_forces_a_daily_rerun(self):
        self.watch(); old = os.path.join(self.d, 'state', 'status'); os.utime(old, (0, 0))
        self.watch(); self.assertEqual(len(self.history()), 2)

    def test_force_always_runs(self):
        self.watch(); self.watch('--force'); self.assertEqual(len(self.history()), 2)

    def test_the_alert_fires_when_the_faulting_set_changes_and_not_on_repeats(self):
        self.watch(); self.assertEqual(self.alerts(), [])
        wr(os.path.join(self.d, 'init.d', 'newsvc'), PY); self.watch(); self.watch('--force'); self.watch('--force')
        self.assertEqual(len(self.alerts()), 1); self.assertIn('none -> newsvc', self.alerts()[0])
        wr(os.path.join(self.d, 'init.d', 'newsvc'), PY + SAFE_STOP); self.watch()
        self.assertEqual(len(self.alerts()), 2); self.assertIn('newsvc -> none', self.alerts()[1])

    def test_alerting_is_off_unless_asked_for(self):
        wr(os.path.join(self.d, 'init.d', 'newsvc'), PY); self.watch(alert=False)
        self.assertEqual(self.alerts(), [])

    def test_a_lint_change_triggers_a_run(self):
        copy = os.path.join(self.d, 'lintcopy'); wr(copy, rd(LINT)); self.watch()
        env = dict(os.environ, HONEY_INITD_LINT=copy, HONEY_INITD_DIR=self.d + '/init.d', HONEY_INITD_CONFD=self.d + '/conf.d', HONEY_INITD_LINT_STATE=self.d + '/state')
        subprocess.run(['bash', WATCH], env=env, capture_output=True, timeout=60)
        wr(copy, rd(LINT) + '\n# changed\n'); subprocess.run(['bash', WATCH], env=env, capture_output=True, timeout=60)
        self.assertEqual(len(self.history()), 3)

    def test_a_missing_lint_is_exit_2_and_writes_nothing(self):
        env = dict(os.environ, HONEY_INITD_LINT='/nonexistent/lint', HONEY_INITD_LINT_STATE=self.d + '/state')
        self.assertEqual(subprocess.run(['bash', WATCH], env=env, capture_output=True).returncode, 2)
        self.assertEqual(self.history(), [])


@unittest.skipUnless(PROOF, 'SKIPPED: initd-stop-proof is not beside this test')
class StopProofGate(unittest.TestCase):
    """The namespace proof must refuse BEFORE it mounts or starts anything when it is not inside a private PID namespace.
    These run without root: they call its inside-half directly, in the host namespace, and expect the gate to say no."""
    def run_inside(self, hostns):
        return subprocess.run(['bash', PROOF, '--inside', hostns, tempfile.gettempdir(), os.devnull], capture_output=True, text=True, timeout=60)

    def test_refuses_in_the_host_pid_namespace(self):
        p = self.run_inside(os.readlink('/proc/self/ns/pid'))
        self.assertEqual(p.returncode, 5, p.stdout + p.stderr); self.assertIn('GATE REFUSED', p.stdout)

    def test_refuses_when_pid_is_not_an_early_namespace_pid(self):
        p = self.run_inside('pid:[0]')
        self.assertEqual(p.returncode, 5, p.stdout + p.stderr)
        self.assertNotIn('GATE:', p.stdout)

    def test_the_gate_precedes_every_mount_and_every_start_in_the_source(self):
        text = rd(PROOF)
        inside = text[text.index('if [ "${1:-}" = --inside ]'):]
        gate_end = inside.index('say "GATE:')
        before = inside[:gate_end]
        self.assertIn('mount -t tmpfs tmpfs /run', before)
        self.assertNotIn('openrc-run', '\n'.join(l for l in before.splitlines() if not l.strip().startswith('#')))
        code = '\n'.join(l for l in before.splitlines() if not l.strip().startswith('#'))
        self.assertNotRegex(code, r'(^|\s)(start_all|mkunit)\b|units/[a-z-]+" start')
        for tag in ('GATE REFUSED', 'ns/pid', '/proc/1/cmdline', 'stat -f -c %T /run', 'ls -A /run', 'llama-swap', 'identity_proxy', '*.pid'):
            self.assertIn(tag, before, tag)

    def test_the_proof_refuses_to_say_proven_when_the_control_is_vacuous(self):
        text = rd(PROOF)
        self.assertRegex(text, r'CONTROL" != reproduced \]; then say "RESULT: CONTROL DID NOT REPRODUCE.*exit 3')

    def test_the_proof_labels_its_own_claim(self):
        text = rd(PROOF)
        self.assertIn('this stop function signals only its own pid', text)
        self.assertIn('NOT shown: that the default no longer mass-kills on the real host', text)


if __name__ == '__main__':
    unittest.main(verbosity=2)
